import { GRID_COLOUR_SETS, GRID_SYMBOL_SETS, gridTypeKey, isGridValue, type GridColourSet, type GridSymbolSet } from "./grid.ts";

export type Language = "python" | "typescript";
export type ObjectValue = number | string;
export type ObjectType = "Int" | "string" | "Grid";

/**
 * GridTypes that ship offline calibration tables (lib/game-utilities/src/grid/data, generated by
 * lib/grid-lab). Rooms may only select these; a game-utilities test keeps the two lists equal.
 */
export const SHIPPED_GRID_TYPE_KEYS: readonly string[] = Object.freeze([
  "Grid(5,base10,rgby)", "Grid(3,base10,rgb)", "Grid(4,base12,rgb)", "Grid(6,cards,rainbow6)",
]);

export interface GameSettings {
  language: Language;
  objectType: ObjectType;
  intMin: number;
  intMax: number;
  stringMaxLength: number;
  /** Grid only: side length N (the grid is N×N). */
  gridSize: number;
  /** Grid only: the symbol set printed on cells. */
  gridSymbols: GridSymbolSet;
  /** Grid only: the colour set. */
  gridColours: GridColourSet;
  /** Grid only: energy (bits) each agent earns per second of world time, into its own account. */
  agentEnergyPerSecond: number;
  /** Grid only: an agent's energy is capped at this many of its expected acts. */
  agentBatteryActs: number;
  grammarId: string;
  /** How utility functions are dealt to gods; see @workspace/game-utilities. */
  utilitySelectorId: string;
  complexityFunctionId: string;
  spawnFunctionId: "uniform";
  planningSeconds: number;
  halfLifeSeconds: number;
  startingObjectCount: number;
  spawnRateHz: number;
  interactionRateHz: number;
  /** Guest execution CPU budget per interaction; excludes compilation and startup. */
  interactionComputeMs: number;
  pauseSeconds: number;
  startingEnergy: number;
  energyPerSecond: number;
}

// These IDs describe the contract, not a claim that runners are installed.
export const DEFAULT_SETTINGS: Readonly<GameSettings> = Object.freeze({
  language: "python",
  objectType: "Int",
  intMin: -2147483648,
  intMax: 2147483647,
  stringMaxLength: 128,
  gridSize: 5,
  gridSymbols: "base10",
  gridColours: "rgby",
  agentEnergyPerSecond: 2,
  agentBatteryActs: 2,
  grammarId: "python-standard-v1",
  utilitySelectorId: "divine-lottery",
  complexityFunctionId: "ast-bytes-v1",
  spawnFunctionId: "uniform",
  planningSeconds: 60,
  halfLifeSeconds: 300,
  startingObjectCount: 10,
  spawnRateHz: 0.1,
  interactionRateHz: 100,
  interactionComputeMs: 5,
  pauseSeconds: 180,
  startingEnergy: 100,
  energyPerSecond: 1,
});

export const SETTINGS_OPTIONS = {
  grammarId: [
    { id: "python-standard-v1", label: "Python computational standard library", languages: ["python"], objectTypes: ["Int", "string", "Grid"] },
    { id: "typescript-standard-v1", label: "TypeScript ECMAScript built-ins", languages: ["typescript"], objectTypes: ["Int", "string", "Grid"] },
  ],
  utilitySelectorId: [
    { id: "divine-lottery", label: "Divine Lottery (each god draws a random utility function)", languages: ["python", "typescript"], objectTypes: ["Int", "string", "Grid"] },
  ],
  complexityFunctionId: [
    { id: "ast-bytes-v1", label: "AST nodes + literal bytes", languages: ["python", "typescript"], objectTypes: ["Int", "string", "Grid"] },
  ],
};

/** Validate mathematical settings and pre-authored options, independently of resource limits. */
export function validateSettings(settings: GameSettings): void {
  if (!["python", "typescript"].includes(settings.language)) {
    throw new Error("Unsupported language");
  }
  if (!["Int", "string", "Grid"].includes(settings.objectType)) {
    throw new Error("Unsupported object type");
  }
  if (settings.objectType === "Grid") {
    if (!(GRID_SYMBOL_SETS as readonly string[]).includes(settings.gridSymbols) ||
        !(GRID_COLOUR_SETS as readonly string[]).includes(settings.gridColours) ||
        !SHIPPED_GRID_TYPE_KEYS.includes(gridTypeKey(gridArgs(settings)))) {
      throw new Error(`Unsupported grid: choose one of ${SHIPPED_GRID_TYPE_KEYS.join(", ")}`);
    }
    for (const key of ["agentEnergyPerSecond", "agentBatteryActs"] as const) {
      if (!Number.isFinite(settings[key]) || settings[key] < 0 || settings[key] > 1000) {
        throw new Error(`${key} must be finite, from 0 to 1000`);
      }
    }
  }
  if (
    !Number.isSafeInteger(settings.intMin) ||
    !Number.isSafeInteger(settings.intMax) ||
    settings.intMin < -2147483648 ||
    settings.intMax > 2147483647 ||
    settings.intMin > settings.intMax
  ) {
    throw new Error("Integer bounds must lie within the signed 32-bit domain");
  }
  for (const key of ["stringMaxLength", "startingObjectCount"] as const) {
    if (!Number.isSafeInteger(settings[key]) || settings[key] < 0) {
      throw new Error(`${key} must be a nonnegative safe integer`);
    }
  }
  for (const key of [
    "planningSeconds", "halfLifeSeconds", "spawnRateHz",
    "interactionRateHz", "pauseSeconds", "startingEnergy", "energyPerSecond",
  ] as const) {
    if (!Number.isFinite(settings[key]) || settings[key] < 0) {
      throw new Error(`${key} must be finite and nonnegative`);
    }
  }
  if (settings.halfLifeSeconds === 0) throw new Error("Half-life must be positive");
  if (settings.interactionRateHz > 1000) throw new Error("interactionRateHz must not exceed 1000 Hz");
  if (!Number.isInteger(settings.interactionComputeMs) ||
      settings.interactionComputeMs < 1 || settings.interactionComputeMs > 1000) {
    throw new Error("interactionComputeMs must be an integer from 1 to 1000 milliseconds");
  }
  if (settings.pauseSeconds === 0) throw new Error("Pause duration must be positive");
  if (settings.spawnFunctionId !== "uniform") throw new Error("Unsupported spawn function");
  for (const key of ["grammarId", "utilitySelectorId", "complexityFunctionId"] as const) {
    if (!SETTINGS_OPTIONS[key].some(option => option.id === settings[key] &&
        option.languages.includes(settings.language) && option.objectTypes.includes(settings.objectType))) {
      throw new Error(`Unsupported ${key} for this language and object type`);
    }
  }
}

/** The GridType parameters of Grid settings. */
export function gridArgs(settings: Pick<GameSettings, "gridSize" | "gridSymbols" | "gridColours">) {
  return { size: settings.gridSize, symbols: settings.gridSymbols, colours: settings.gridColours };
}

/** Reject rather than coerce, truncate, wrap, or clamp invalid runner outputs. */
export function assertObjectValue(
  value: unknown,
  settings: Pick<GameSettings, "objectType" | "intMin" | "intMax" | "stringMaxLength"> &
    Partial<Pick<GameSettings, "gridSize" | "gridSymbols" | "gridColours">>,
): asserts value is ObjectValue {
  if (settings.objectType === "Grid") {
    if (!isGridValue(value, gridArgs(settings as GameSettings))) throw new Error("Expected a canonical grid of the room's grid type");
  } else if (settings.objectType === "Int") {
    if (
      typeof value !== "number" || !Number.isSafeInteger(value) ||
      value < settings.intMin || value > settings.intMax
    ) throw new Error("Expected an integer within the room's configured bounds");
  } else if (
    typeof value !== "string" || value.length > settings.stringMaxLength ||
    /[^\x00-\x7f]/u.test(value)
  ) {
    throw new Error("Expected an ASCII string within the room's configured length cap");
  }
}
